            &&& (forall |block_id| map.dom().contains(block_id) ==>
                    map[block_id].instance_id() == inst.id())

            &&& points_to.is_range(block_start_at(llgstr1.page_id, llgstr1.block_size as int, 0), n_blocks * llgstr1.block_size)
